// 聚合統計：AI 不擅長算數，數字先在 Code 算好再給 AI 寫摘要
const alerts = $json.alerts || [];
const bySeverity = {};
const byHost = {};
const byAlertname = {};
for (const a of alerts) {
  bySeverity[a.severity] = (bySeverity[a.severity] || 0) + 1;
  byHost[a.host] = (byHost[a.host] || 0) + 1;
  byAlertname[a.alertname] = (byAlertname[a.alertname] || 0) + 1;
}
const topHosts = Object.entries(byHost).sort((a, b) => b[1] - a[1]).slice(0, 3)
  .map(([h, c]) => `${h}（${c} 次）`);
const summary = {
  total: alerts.length,
  critical: bySeverity.critical || 0,
  warning: bySeverity.warning || 0,
  top_hosts: topHosts,
  by_alertname: byAlertname,
  first_alert: alerts[0]?.timestamp || null,
  last_alert: alerts[alerts.length - 1]?.timestamp || null
};
return [{ json: { stats: summary } }];

const text = $json.candidates?.[0]?.content?.parts?.[0]?.text || '(Gemini 未回傳內容)';
const report = text.replace(/```(markdown)?\n?|```/g, '').trim();
const stats = $('統計聚合').item.json.stats;
return [{ json: {
  report_date: new Date().toISOString().slice(0, 10),
  total_alerts: stats.total,
  critical_count: stats.critical,
  report_markdown: report
} }];
